import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.D45daZFh.js";const b=JSON.parse('{"title":"成人慢性肾脏病食养指南（2024年版）","description":"国家卫健委《成人慢性肾脏病食养指南（2024年版）》要点导读：按分期分型食养，控制盐油糖，蛋白质个体化。","frontmatter":{"title":"成人慢性肾脏病食养指南（2024年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2024年版","published":"2024-02","document_no":"国卫办食品函〔2024〕53号","source_url":"https://www.nhc.gov.cn/sps/c100088/202402/9ba512ba8e314a47a181db11d2fa188d/files/1743476135509_49966.pdf","status":"现行","tags":["慢性肾脏病","食养","饮食指导"],"reviewed":false,"description":"国家卫健委《成人慢性肾脏病食养指南（2024年版）》要点导读：按分期分型食养，控制盐油糖，蛋白质个体化。"},"headers":[],"relativePath":"guides/ckd-2024.md","filePath":"guides/ckd-2024.md"}'),s={name:"guides/ckd-2024.md"};function d(n,t,i,l,c,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="成人慢性肾脏病食养指南-2024年版" tabindex="-1">成人慢性肾脏病食养指南（2024年版） <a class="header-anchor" href="#成人慢性肾脏病食养指南-2024年版" aria-label="Permalink to &quot;成人慢性肾脏病食养指南（2024年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本导读由 AI 起草，尚未逐条对照原文校验；一切以原文为准。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/sps/c100088/202402/9ba512ba8e314a47a181db11d2fa188d/files/1743476135509_49966.pdf" target="_blank" rel="noreferrer">官方问答 PDF</a>，指南全文另见<a href="https://www.chinanutri.cn/fgbz/fgbzjszn/" target="_blank" rel="noreferrer">中国疾控中心营养与健康所技术指南页</a>）· 一级来源</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>成人慢性肾脏病患者及其家人。<strong>特别提示：肾病饮食与病程分期高度相关，务必在医生或营养师指导下执行，不要自行套用他人的食谱。</strong></p><h2 id="关键要点-摘要" tabindex="-1">关键要点（摘要） <a class="header-anchor" href="#关键要点-摘要" aria-label="Permalink to &quot;关键要点（摘要）&quot;">​</a></h2><ul><li><strong>按分期分型食养</strong>：指南根据疾病特点、分期和分型分别给出食养原则，不同阶段要求不同。</li><li><strong>控制盐、油、糖用量</strong>：日常膳食清淡化。</li><li><strong>少吃过度加工食品</strong>：减少烟熏、烧烤、腌制食品。</li><li><strong>蛋白质摄入个体化</strong>：数量与种类需结合分期确定，详见原文。</li></ul><h2 id="怎么用这份文件" tabindex="-1">怎么用这份文件 <a class="header-anchor" href="#怎么用这份文件" aria-label="Permalink to &quot;怎么用这份文件&quot;">​</a></h2><p>先确认自己的分期（问主治医生），再翻对应章节；指南附分地区、分季节食谱示例与食养方，具体以原文为准。</p><h2 id="溯源信息" tabindex="-1">溯源信息 <a class="header-anchor" href="#溯源信息" aria-label="Permalink to &quot;溯源信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2024 年版（现行）</td></tr><tr><td>印发时间</td><td>2024 年 2 月（具体日期待核对原文）</td></tr><tr><td>发文字号</td><td>国卫办食品函〔2024〕53号（待人工复核）</td></tr></tbody></table>',11)])])}const p=a(s,[["render",d]]);export{b as __pageData,p as default};
